service.method:

/* doSelectSealInfoDeptHead */
SELECT USMT.USER_ID			AS APP_USER_ID 	
	 , USMT.USER_NAME_LOC 	AS APP_USER_NAME
	 , GETDEPTNAME(${session.HOUSE_CODE}, USMT.COMPANY_CODE, USMT.DEPT, '') AS DEPARTMENT_NAME
	 , USMT.DEPT			AS DEPT
	 , USMT.EMPLOYEE_NO		AS EMPLOYEE_NO
	 , USMT.POSITION		AS POSITION
	 , USMT.COMPANY_CODE	AS SELLER_CODE
  FROM SDEPT T1
  INNER JOIN SUSMT USMT ON T1.DEPT = USMT.DEPT AND T1.MANAGER_ID = USMT.USER_ID
 WHERE T1.HOUSE_CODE 	= ${session.HOUSE_CODE}
   AND T1.COMPANY_CODE 	= ${session.COMPANY_CODE}
   AND T1.DEPT 			= ${session.DEPARTMENT}


SELECT
	SUBJECT
FROM
	SUDGL
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND USE_NUMBER = ${SEAL_USE_TYPE}


SELECT
	SMI_NUMBER
	, SUBJECT
FROM
	SSRAD
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMI_NUMBER = ${SMI_NUMBER}


SELECT
	SMR_NUMBER
	,DATA
FROM
	SSIAD_EXTRA_INFO
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}


SELECT 
	APP_NO
FROM 
	SGWGL 
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SUX_WKEY1 = ${SMR_NUMBER}
ORDER BY
	APP_NO DESC


SELECT
	*
FROM
	SSIAD
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}


SELECT
	*
FROM
	SSETL
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}
